from typing import List

class Solution:
    def partitionLabels(self, s: str) -> List[int]:
        L = len(s)
        last = {s[i]: i for i in range(L)}  # last occurrence of each character
        i, ans = 0, []
        while i < L:
            end, j = last[s[i]], i + 1
            while j < end:
                if last[s[j]] > end:
                    end = last[s[j]]
                j += 1
            ans.append(end - i + 1)
            i = end + 1
        return ans

class Solution:
    def moveFinal(self, stones):
        stones.sort()
        n = len(stones)
        # maximum moves
        max_moves = max(stones[-2] - stones[0], stones[-1] - stones[1]) - (n - 2)
        if max_moves == 0:
            return [0, 0]
        # sliding window: largest number of stones that fit in an interval of length n
        left = 0
        max_in_window = 0
        for right in range(n):
            while stones[right] - stones[left] > n - 1:
                left += 1
            max_in_window = max(max_in_window, right - left + 1)
        min_moves = n - max_in_window
        # special case: n-1 stones in a window of length n with a gap > 2
        if max_in_window == n - 1:
            if (stones[-1] - stones[0] == n - 1) and (stones[-1] - stones[-2] > 2 or stones[1] - stones[0] > 2):
                min_moves = 2
        return [min_moves, max_moves]

