class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total = sum(arr)
        if total % 3 != 0:
            return False
        each_sum = total // 3
        cur_sum = 0
        parts = 0
        for num in arr:
            if parts == 2:
                # Found two split points; the rest forms the third part
                return True
            cur_sum += num
            if cur_sum == each_sum:
                cur_sum = 0
                parts += 1
        return False

