from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie for forbidden strings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True

        # Check if a substring contains any forbidden suffix; return its length or False
        def isForbidden(s: str):
            node = trie
            length = 0
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                length += 1
                if "end" in node:
                    return length
            return False

        res = 0
        j = len(word)
        for i in range(len(word) - 1, -1, -1):
            cnt = isForbidden(word[i:j])
            if cnt:
                # shrink left bound to exclude the last character of the found forbidden suffix
                j = i + cnt - 1
            res = max(res, j - i)
        return res

