class Solution:
    def isPossible(self, n: int, edges: list[list[int]]) -> bool:
        # Build adjacency list
        neighbors = [set() for _ in range(n)]
        for a, b in edges:
            a -= 1
            b -= 1
            neighbors[a].add(b)
            neighbors[b].add(a)

        odd = [i for i in range(n) if len(neighbors[i]) % 2 == 1]
        m = len(odd)

        if m == 0:
            return True
        if m == 2:
            u, v = odd
            # If u and v are not connected, adding the edge fixes both
            if v not in neighbors[u]:
                return True
            # Otherwise need a third vertex that is not adjacent to either u or v
            for w in range(n):
                if w != u and w != v and w not in neighbors[u] and w not in neighbors[v]:
                    return True
            return False
        if m == 4:
            # Check if any pair of odd vertices is not already connected
            for i in range(4):
                for j in range(i + 1, 4):
                    if odd[j] not in neighbors[odd[i]]:
                        return True
            return False
        # Any other odd count cannot be fixed
        return False

