from typing import List

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        # Build adjacency list
        tree = [[] for _ in nums]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        total = sum(nums)

        # DFS returns the sum of the subtree that cannot yet form a complete component.
        # If the subtree sum equals the candidate component sum, it is reset to 0.
        def dfs(u: int, parent: int) -> int:
            s = nums[u]
            for v in tree[u]:
                if v != parent:
                    s += dfs(v, u)
            # If this subtree exactly matches the target component sum, treat it as a component.
            return 0 if s == cand else s

        # Try every possible component sum (divisor of total, except total itself)
        for cand in range(1, total // 2 + 1):
            if total % cand == 0 and dfs(0, -1) == 0:
                # Number of components = total // cand
                return total // cand
        return 0

