class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0
        M, N = len(grid), len(grid[0])

        def is_magic(i: int, j: int) -> bool:
            # collect the 3x3 sub‑grid
            nums = []
            for r in range(i, i + 3):
                row = grid[r][j:j + 3]
                if len(row) != 3:
                    return False
                nums.extend(row)
            # must contain each number 1‑9 exactly once
            if sorted(nums) != list(range(1, 10)):
                return False
            # check row sums
            for r in range(i, i + 3):
                if sum(grid[r][j:j + 3]) != 15:
                    return False
            # check column sums
            for c in range(j, j + 3):
                if grid[i][c] + grid[i + 1][c] + grid[i + 2][c] != 15:
                    return False
            # check the two diagonals
            if grid[i][j] + grid[i + 1][j + 1] + grid[i + 2][j + 2] != 15:
                return False
            if grid[i][j + 2] + grid[i + 1][j + 1] + grid[i + 2][j] != 15:
                return False
            return True

        res = 0
        for i in range(M - 2):
            for j in range(N - 2):
                if is_magic(i, j):
                    res += 1
        return res

