from typing import List

class Solution:
    def maxValueAfterReverse(self, nums: List[int]) -> int:
        n = len(nums)
        original = sum(abs(nums[i] - nums[i + 1]) for i in range(n - 1))
        ans = original
        # reverse prefix: make nums[i] the first element
        for i in range(1, n - 1):
            ans = max(ans, original - abs(nums[i] - nums[i + 1]) + abs(nums[i] - nums[0]))
        # reverse suffix: make nums[i] the last element
        for i in range(1, n - 1):
            ans = max(ans, original - abs(nums[i - 1] - nums[i]) + abs(nums[i] - nums[-1]))
        # bring global min and max together
        if n > 2:
            ans = max(ans, original + 2 * (max(nums) - min(nums)))
        return ans

