class Solution:
    def kthLargestLevelSum(self, root: Optional[TreeNode], k: int) -> int:
        if not root:
            return -1
        dq = deque([root])
        level_sums = []
        while dq:
            level_size = len(dq)
            level_sum = 0
            for _ in range(level_size):
                node = dq.popleft()
                level_sum += node.val
                if node.left:
                    dq.append(node.left)
                if node.right:
                    dq.append(node.right)
            level_sums.append(level_sum)
        if k > len(level_sums):
            return -1
        level_sums.sort(reverse=True)
        return level_sums[k-1]

