from typing import List

class Solution:
    def checkValid(self, matrix: List[List[int]]) -> bool:
        n = len(matrix)
        # Ensure the matrix is square
        if n == 0 or any(len(row) != n for row in matrix):
            return False

        # dp_row[i][v] = True if value v+1 appears in row i
        # dp_col[j][v] = True if value v+1 appears in column j
        dp_row = [[False] * n for _ in range(n)]
        dp_col = [[False] * n for _ in range(n)]

        return self.helper(matrix, dp_row, dp_col)

    def helper(self, matrix, dp_row, dp_col):
        n = len(matrix)
        for i in range(n):
            for j in range(n):
                val = matrix[i][j]
                # values must be in range 1..n
                if val < 1 or val > n:
                    return False
                idx = val - 1
                if dp_row[i][idx] or dp_col[j][idx]:
                    return False
                dp_row[i][idx] = True
                dp_col[j][idx] = True
        return True

